def next_smallest_palindrome(n: int) -> int:
    s = str(n)
    length = len(s)

    # Helper to check if all digits are '9'
    if all(ch == '9' for ch in s):
        # Next palindrome after 999...9 is 100...001 (length+1 digits)
        return int('1' + ('0' * (length - 1)) + '1')

    def make_palindrome(left: str, odd_length: bool) -> int:
        if odd_length:
            return int(left + left[-2::-1])
        else:
            return int(left + left[::-1])

    # Increment the number to ensure strictly greater palindrome
    n += 1
    s = str(n)
    length = len(s)
    odd = length % 2 != 0
    half_len = (length + 1) // 2  # length of left half including middle if odd

    left = s[:half_len]
    p = make_palindrome(left, odd)

    if p >= n:
        return p
    # If palindrome <= n, we need to increment the left half and rebuild
    left_num = int(left) + 1
    left = str(left_num)
    # If incrementing left increases length, it means palindrome length grows by 1
    if len(left) > half_len:
        # For example, 999 -> after increment left half length grows,
        # palindrome is 100...001 with length+1 digits
        return int('1' + ('0' * (length - 1)) + '1')
    return make_palindrome(left, odd)

