import math

def min_Jumps(length: float, d: float) -> int:
    if d <= 0:
        return 0
    # If length >= d, one jump suffices
    if length >= d:
        return 1
    # Otherwise, calculate minimal jumps to reach or pass d on x-axis
    # Since each jump is length and direction can be chosen, 
    # we can align jumps perfectly along x-axis.
    # So minimal jumps is ceil(d / length)
    return math.ceil(d / length)

from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    groups = paren_string.split()
    result = []

    for group in groups:
        max_depth = 0
        current_depth = 0
        for ch in group:
            if ch == '(':
                current_depth += 1
                if current_depth > max_depth:
                    max_depth = current_depth
            elif ch == ')':
                current_depth -= 1
        result.append(max_depth)

    return result

